{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_by_id = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n['parent']
        if p is not None:
            children[p].append(n['id'])
    symbol_count = {}
    for n in nodes:
        s = n['symbol']
        symbol_count[s] = symbol_count.get(s, 0) + 1
    retained = set(node_by_id.keys())
    root_id = [n['id'] for n in nodes if n['parent'] is None][0]
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removal_order = []
    for n in sorted_nodes:
        nid = n['id']
        if not n['removable']:
            continue
        if nid == root_id:
            continue
        if n['symbol'] in required_symbols:
            continue
        # check if any child is still retained
        child_retained = any(cid in retained for cid in children[nid])
        if child_retained:
            continue
        sym = n['symbol']
        if symbol_count.get(sym, 0) == 1 and sym in required_symbols:
            continue
        # proceed with removal
        removal_order.append(nid)
        retained.remove(nid)
        symbol_count[sym] = symbol_count.get(sym, 0) - 1
    retained_list = sorted(retained)
    return {'retained': retained_list, 'removal_order': removal_order}"
}
